//! A small precision platformer: no assets, a fixed simulation, and forgiving jumps.
//!
//! The native entry point opens the interactive renderer. The browser retains the
//! exports generated by `ferravex_render::game!`.
//!
//! ```no_run
//! emberline::run();
//! ```
//!
//! The private simulation and its tests use the same session as the host: Ready
//! waits for confirmation, Paused freezes the trial, and Won freezes the result.
//! Fixed-tick input is consumed only when `GameSession::advance` schedules work.
mod animation;
#[cfg(all(debug_assertions, not(target_arch = "wasm32")))]
mod capture;
mod compact;
mod hud;
#[cfg(test)]
mod journey200_tests;
mod juice;
mod presentation;
mod quips;
